"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('hale', 26), ('ivory', 43), ('hale', 31), ('hale', 10), ('hale', 16), ('juno', 47)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)


def feed_invoices():
    """Endless feed of invoices: repeats the stored rows for ever."""
    while True:
        for client, due in ROWS:
            yield Invoice(client, due)

