"""Windows over the invoices feed."""
import itertools


def summarize_window(feed, size):
    """Read the next `size` invoices from the feed and return (peak due, list of due).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = itertools.islice(feed, size)
    peak = max(x.due for x in window)
    values = [x.due for x in window]
    return peak, values


def group_by_client(invoices):
    """Return a dict from client to the list of invoices with that client."""
    groups = {}
    for x in invoices:
        groups.setdefault(x.client, []).append(x)
    return groups


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)
